<?php
namespace App\Services;use App\Models\{TransportService,TransportSetting};use Carbon\CarbonInterface;
class TransportSchedulingConflictService{public function conflicts(int$companyId,CarbonInterface$start,CarbonInterface$end,?int$vehicle,?int$driver,?int$monitor,?int$exclude=null):array{$padding=TransportSetting::where('company_id',$companyId)->value('turnaround_minutes')??0;$from=$start->copy()->subMinutes($padding);$to=$end->copy()->addMinutes($padding);$base=TransportService::forCompany($companyId)->whereNot('status','cancelled')->where('scheduled_start_at','<',$to)->where('scheduled_arrival_at','>',$from);if($exclude)$base->whereKeyNot($exclude);$result=[];foreach(['vehicle'=>$vehicle,'driver'=>$driver,'monitor'=>$monitor]as$type=>$id)if($id&&(clone$base)->where('planned_'.$type.'_id',$id)->exists())$result[]=$type;return$result;}public function hasRouteConflict(int$companyId,int$routeId,CarbonInterface$start,CarbonInterface$end,?int$exclude=null):bool{$q=TransportService::forCompany($companyId)->where('transport_route_id',$routeId)->whereNot('status','cancelled')->where('scheduled_start_at','<',$end)->where('scheduled_arrival_at','>',$start);if($exclude)$q->whereKeyNot($exclude);return$q->exists();}}
